def audit_matrix(X):
    X = np.asarray(X, dtype=float)
    return {
        'shape': X.shape,
        'missing': int(np.isnan(X).sum()),
        'mean': X.mean(axis=0).tolist(),
        'std': X.std(axis=0).tolist(),
        'rank': int(np.linalg.matrix_rank(X - X.mean(axis=0)))
    }

import numpy as np

def f(v):
    x, y = v
    return x*x + 2*y*y

def grad_analytic(v):
    x, y = v
    return np.array([2*x, 4*y], dtype=float)

def grad_fd(f, v, h=1e-5):
    v = np.array(v, dtype=float)
    g = np.zeros_like(v)
    for i in range(len(v)):
        e = np.zeros_like(v); e[i] = 1.0
        g[i] = (f(v+h*e)-f(v-h*e))/(2*h)
    return g

v = np.array([1.,2.])
