def f(w):
    return 0.5*(w-3.0)**2

def grad(w):
    return w-3.0

def run(alpha, w=0.0, steps=8):
    trace=[]
    for k in range(steps):
        g=grad(w)
        step=-alpha*g
        trace.append((k,w,f(w),abs(g),abs(step)))
        w=w+step
    return trace

for a in (0.1,0.5,1.5,2.2):
    print(a, run(a, steps=5))
